"""Offline receipt metadata and a declarative release contract.

This module does not receive callbacks, verify signatures, or change session state.
"""
import json

RELEASE_CONTRACT = {'schema_version': 1, 'package': 'callback-receipt', 'version': '1.0.0', 'target': 'partner-callback-receipt', 'mode': 'declarative_fixture', 'required_checks': ['issuer', 'request_binding', 'source_signature', 'status']}


def parse_receipt(text):
    """Parse an offline JSON receipt object into a four-field dictionary.

    receipt_id, request_id, and provider must be nonempty strings. status must be
    'delivered' or 'rejected'. Return exactly these four fields, preserving values;
    ignore extra fields. Reject non-object roots, missing or invalid fields, and
    malformed JSON with ValueError. This function only processes synthetic metadata.
    """
    try:
        obj = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError(str(exc)) from exc
    if not isinstance(obj, dict):
        raise ValueError('root must be a JSON object')
    required = ('receipt_id', 'request_id', 'provider', 'status')
    for field in required:
        if field not in obj:
            raise ValueError(f'missing field: {field}')
    for field in ('receipt_id', 'request_id', 'provider'):
        if not isinstance(obj[field], str) or not obj[field]:
            raise ValueError(f'{field} must be a nonempty string')
    if obj['status'] not in ('delivered', 'rejected'):
        raise ValueError(f'unsupported status: {obj["status"]}')
    return {field: obj[field] for field in required}
